import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { fetchCourses, getForumTopics } from '../../api';
import './Forums.css';

export default function ForumList() {
  const [courses, setCourses] = useState([]);
  const [topics, setTopics] = useState([]);
  const [username, setUsername] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      const [coursesData, topicsData] = await Promise.all([
        fetchCourses(),
        getForumTopics()
      ]);
      setCourses(coursesData);
      setTopics(topicsData);

      const token = localStorage.getItem('token');
      const response = await fetch('http://localhost:8080/api/auth/profile', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (response.ok) {
        const data = await response.json();
        setUsername(data.username);
      }
    } catch (error) {
      console.error('Error loading forum data:', error);
    }
  };

  const recentTopics = topics.slice(0, 10);

  return (
    <div className="forum-container">
      <div className="forum-header">
        <h1>Discussion Forums</h1>
        <button 
          className="create-topic-btn"
          onClick={() => navigate('/forums/create')}
        >
          Create New Topic
        </button>
      </div>

      <div className="forum-sections">
        <div className="course-forums">
          <h2>Course Forums</h2>
          <div className="course-list">
            {courses.map(course => {
              const courseTopics = topics.filter(t => t.courseId === course.id);
              return (
                <div key={course.id} className="course-forum-item">
                  <div className="course-info">
                    <h3>{course.title}</h3>
                    <p>{courseTopics.length} topics</p>
                  </div>
                  <button 
                    onClick={() => navigate(`/forums/course/${course.id}/${course.title}`)}
                    className="view-forum-btn"
                  >
                    View Forum
                  </button>
                </div>
              );
            })}
          </div>
        </div>

        <div className="recent-topics">
          <h2>Recent Discussions</h2>
          <div className="topics-list">
            {recentTopics.map(topic => (
              <div key={topic.id} className="topic-item">
                <div className="topic-content">
                  <h4 onClick={() => navigate(`/forums/topic/${topic.id}`)}>
                    {topic.title}
                  </h4>
                  <p>by {topic.author} • {topic.replies} replies</p>
                  <span className="topic-time">{new Date(topic.createdAt).toLocaleDateString()}</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
